package billing
import("context";"fmt";"strings";"time";"github.com/jackc/pgx/v5/pgxpool")
type Service struct{db *pgxpool.Pool};func NewService(db *pgxpool.Pool)*Service{return &Service{db:db}}
type FeeSchedule struct{ID string `json:"id"`;SchoolID string `json:"school_id"`;SchoolYearID string `json:"school_year_id"`;Name string `json:"name"`;Currency string `json:"currency"`;Status string `json:"status"`};type CreateFeeScheduleInput struct{SchoolPublicID string `json:"school_public_id"`;SchoolYearID string `json:"school_year_id"`;LevelID string `json:"level_id"`;ClassID string `json:"class_id"`;Name string `json:"name"`};type FeeItem struct{ID string `json:"id"`;FeeScheduleID string `json:"fee_schedule_id"`;Code string `json:"code"`;Label string `json:"label"`;Amount int64 `json:"amount"`;Mandatory bool `json:"mandatory"`};type CreateFeeItemInput struct{SchoolPublicID string `json:"school_public_id"`;FeeScheduleID string `json:"fee_schedule_id"`;Code string `json:"code"`;Label string `json:"label"`;Amount int64 `json:"amount"`;Mandatory bool `json:"mandatory"`;Refundable bool `json:"refundable"`;DisplayOrder int `json:"display_order"`};type InstallmentPlan struct{ID string `json:"id"`;FeeScheduleID string `json:"fee_schedule_id"`;Name string `json:"name"`;AllowPartialPayment bool `json:"allow_partial_payment"`};type CreatePlanInput struct{SchoolPublicID string `json:"school_public_id"`;FeeScheduleID string `json:"fee_schedule_id"`;Name string `json:"name"`;AllowPartialPayment bool `json:"allow_partial_payment"`};type Installment struct{ID string `json:"id"`;PlanID string `json:"installment_plan_id"`;Sequence int `json:"sequence"`;Label string `json:"label"`;Amount int64 `json:"amount"`;DueDate time.Time `json:"due_date"`};type CreateInstallmentInput struct{SchoolPublicID string `json:"school_public_id"`;PlanID string `json:"installment_plan_id"`;Sequence int `json:"sequence"`;Label string `json:"label"`;Amount int64 `json:"amount"`;DueDate string `json:"due_date"`};type ActivateEnrollmentInput struct{SchoolPublicID string `json:"school_public_id"`;EnrollmentPublicID string `json:"enrollment_public_id"`;FeeScheduleID string `json:"fee_schedule_id"`;InstallmentPlanID string `json:"installment_plan_id"`};type ActivationResult struct{EnrollmentPublicID string `json:"enrollment_public_id"`;Status string `json:"status"`;ChargesCreated int64 `json:"charges_created"`;TotalAmount int64 `json:"total_amount"`}
func(s *Service)CreateFeeSchedule(ctx context.Context,in CreateFeeScheduleInput)(FeeSchedule,error){if strings.TrimSpace(in.Name)==""{return FeeSchedule{},fmt.Errorf("name is required")};if in.LevelID==""&&in.ClassID==""{return FeeSchedule{},fmt.Errorf("level_id or class_id is required")};var o FeeSchedule;e:=s.db.QueryRow(ctx,`INSERT INTO fee_schedules(school_id,school_year_id,level_id,class_id,name) SELECT s.id,sy.id,NULLIF($3,'')::uuid,NULLIF($4,'')::uuid,$5 FROM schools s JOIN school_years sy ON sy.id=$2::uuid AND sy.school_id=s.id WHERE s.public_id=$1 AND (NULLIF($3,'') IS NULL OR EXISTS(SELECT 1 FROM levels l WHERE l.id=$3::uuid AND l.school_id=s.id)) AND (NULLIF($4,'') IS NULL OR EXISTS(SELECT 1 FROM classes c WHERE c.id=$4::uuid AND c.school_id=s.id AND c.school_year_id=sy.id)) RETURNING id::text,school_id::text,school_year_id::text,name,currency,status`,in.SchoolPublicID,in.SchoolYearID,in.LevelID,in.ClassID,in.Name).Scan(&o.ID,&o.SchoolID,&o.SchoolYearID,&o.Name,&o.Currency,&o.Status);return o,e}
func(s *Service)CreateFeeItem(ctx context.Context,in CreateFeeItemInput)(FeeItem,error){if in.Amount<0||in.Code==""||in.Label==""{return FeeItem{},fmt.Errorf("valid code, label and amount are required")};var o FeeItem;e:=s.db.QueryRow(ctx,`INSERT INTO fee_items(fee_schedule_id,code,label,amount,mandatory,refundable,display_order) SELECT fs.id,$3,$4,$5,$6,$7,$8 FROM fee_schedules fs JOIN schools s ON s.id=fs.school_id WHERE fs.id=$2::uuid AND s.public_id=$1 RETURNING id::text,fee_schedule_id::text,code,label,amount,mandatory`,in.SchoolPublicID,in.FeeScheduleID,in.Code,in.Label,in.Amount,in.Mandatory,in.Refundable,in.DisplayOrder).Scan(&o.ID,&o.FeeScheduleID,&o.Code,&o.Label,&o.Amount,&o.Mandatory);return o,e}
func(s *Service)CreatePlan(ctx context.Context,in CreatePlanInput)(InstallmentPlan,error){var o InstallmentPlan;e:=s.db.QueryRow(ctx,`INSERT INTO installment_plans(fee_schedule_id,name,allow_partial_payment) SELECT fs.id,$3,$4 FROM fee_schedules fs JOIN schools s ON s.id=fs.school_id WHERE fs.id=$2::uuid AND s.public_id=$1 RETURNING id::text,fee_schedule_id::text,name,allow_partial_payment`,in.SchoolPublicID,in.FeeScheduleID,in.Name,in.AllowPartialPayment).Scan(&o.ID,&o.FeeScheduleID,&o.Name,&o.AllowPartialPayment);return o,e}
func(s *Service)CreateInstallment(ctx context.Context,in CreateInstallmentInput)(Installment,error){due,e:=time.Parse("2006-01-02",in.DueDate);if e!=nil{return Installment{},fmt.Errorf("invalid due_date")};if in.Sequence<1||in.Amount<0{return Installment{},fmt.Errorf("invalid sequence or amount")};var o Installment;e=s.db.QueryRow(ctx,`INSERT INTO installments(installment_plan_id,sequence,label,amount,due_date) SELECT ip.id,$3,$4,$5,$6 FROM installment_plans ip JOIN fee_schedules fs ON fs.id=ip.fee_schedule_id JOIN schools s ON s.id=fs.school_id WHERE ip.id=$2::uuid AND s.public_id=$1 RETURNING id::text,installment_plan_id::text,sequence,label,amount,due_date`,in.SchoolPublicID,in.PlanID,in.Sequence,in.Label,in.Amount,due).Scan(&o.ID,&o.PlanID,&o.Sequence,&o.Label,&o.Amount,&o.DueDate);return o,e}
func(s *Service)ActivateEnrollment(ctx context.Context,in ActivateEnrollmentInput)(ActivationResult,error){tx,e:=s.db.Begin(ctx);if e!=nil{return ActivationResult{},e};defer tx.Rollback(ctx);var eid,studentID,schoolID,classID,levelID,yearID,status string;e=tx.QueryRow(ctx,`SELECT e.id::text,e.student_id::text,e.school_id::text,e.class_id::text,c.level_id::text,e.school_year_id::text,e.status FROM enrollments e JOIN schools s ON s.id=e.school_id JOIN classes c ON c.id=e.class_id WHERE s.public_id=$1 AND e.public_id=$2 FOR UPDATE`,in.SchoolPublicID,in.EnrollmentPublicID).Scan(&eid,&studentID,&schoolID,&classID,&levelID,&yearID,&status);if e!=nil{return ActivationResult{},e};if status=="ACTIVE"{return ActivationResult{},fmt.Errorf("enrollment already active")};var sy,ss string;var sl,sc *string;e=tx.QueryRow(ctx,`SELECT fs.school_year_id::text,fs.school_id::text,fs.level_id::text,fs.class_id::text FROM fee_schedules fs JOIN schools s ON s.id=fs.school_id WHERE fs.id=$2::uuid AND s.public_id=$1 AND fs.status IN('DRAFT','ACTIVE')`,in.SchoolPublicID,in.FeeScheduleID).Scan(&sy,&ss,&sl,&sc);if e!=nil{return ActivationResult{},e};if sy!=yearID||ss!=schoolID{return ActivationResult{},fmt.Errorf("fee schedule does not belong to enrollment tenant/year")};if sc!=nil&&*sc!=classID{return ActivationResult{},fmt.Errorf("fee schedule does not apply to class")};if sc==nil&&(sl==nil||*sl!=levelID){return ActivationResult{},fmt.Errorf("fee schedule does not apply to level")};var ps string;e=tx.QueryRow(ctx,`SELECT ip.fee_schedule_id::text FROM installment_plans ip JOIN fee_schedules fs ON fs.id=ip.fee_schedule_id WHERE ip.id=$1::uuid AND fs.school_id=$2::uuid`,in.InstallmentPlanID,schoolID).Scan(&ps);if e!=nil{return ActivationResult{},e};if ps!=in.FeeScheduleID{return ActivationResult{},fmt.Errorf("installment plan does not belong to fee schedule")};var items,total int64;_ = tx.QueryRow(ctx,`SELECT COALESCE(sum(amount),0) FROM fee_items WHERE fee_schedule_id=$1::uuid AND mandatory=true`,in.FeeScheduleID).Scan(&items);_ = tx.QueryRow(ctx,`SELECT COALESCE(sum(i.amount),0) FROM installments i JOIN installment_plans ip ON ip.id=i.installment_plan_id JOIN fee_schedules fs ON fs.id=ip.fee_schedule_id WHERE ip.id=$1::uuid AND fs.school_id=$2::uuid`,in.InstallmentPlanID,schoolID).Scan(&total);if items<=0{return ActivationResult{},fmt.Errorf("fee schedule has no mandatory fees")};if items!=total{return ActivationResult{},fmt.Errorf("installment total %d does not match mandatory fee total %d",total,items)};tag,e:=tx.Exec(ctx,`INSERT INTO student_charges(school_id,student_id,enrollment_id,installment_id,label,original_amount,net_amount,balance,due_date,status) SELECT $1::uuid,$2::uuid,$3::uuid,i.id,i.label,i.amount,i.amount,i.amount,i.due_date,CASE WHEN i.due_date<CURRENT_DATE THEN 'OVERDUE' WHEN i.due_date=CURRENT_DATE THEN 'DUE' ELSE 'UPCOMING' END FROM installments i JOIN installment_plans ip ON ip.id=i.installment_plan_id JOIN fee_schedules fs ON fs.id=ip.fee_schedule_id WHERE ip.id=$4::uuid AND fs.school_id=$1::uuid`,schoolID,studentID,eid,in.InstallmentPlanID);if e!=nil{return ActivationResult{},e};if tag.RowsAffected()==0{return ActivationResult{},fmt.Errorf("installment plan has no installments")};_,e=tx.Exec(ctx,`UPDATE enrollments SET status='ACTIVE',validated_at=now(),updated_at=now() WHERE id=$1::uuid AND school_id=$2::uuid`,eid,schoolID);if e!=nil{return ActivationResult{},e};if e=tx.Commit(ctx);e!=nil{return ActivationResult{},e};return ActivationResult{in.EnrollmentPublicID,"ACTIVE",tag.RowsAffected(),total},nil}
